/* ---------- restart: восстановить исходный порядок из DOM ---------- */
const origOrders = qsa(".disc-list", wizard).map((ul) =>
  qsa("li", ul).map((li) => Array.from(li.childNodes).map((n) => ({ type: li.dataset.type, text: (n.nodeType === 3 ? n.textContent : n.outerHTML).trim() })).filter(Boolean)
);
// Зафиксируем исходный порядок текстов один раз при старте
const initialLists = qsa(".disc-list", wizard).map((ul) => {
  const lis = qsa("li", ul);
  const save = lis.map((li) => {
    const handle = qs(".disc-handle", li);
    const rank = qs(".disc-rank", li);
    const text = li.textContent.replace(handle ? "" : "", "").trim();
    return { text: text, type: li.getAttribute("data-type") };
  });
  return save;
});

qs("#restartBtn").addEventListener("click", () => {
  const lists = qsa(".disc-list", wizard);
  lists.forEach((ul, li) => {
    const orig = initialLists[li];
    const items = qsa("li", ul);
    orig.forEach((o, i) => {
      items[i].dataset.type = o.type;
      // заменим текст, сохранив rank и handle
      const rank = qs(".disc-rank", items[i]);
      const handle = qs(".disc-handle", items[i]);
      items[i].textContent = o.text;
      if (rank) items[i].prepend(rank);
      if (handle) items[i].appendChild(handle);
      refreshRanks(ul);
    });
  });
  closeModal(resultModal);
  lastScore = null;
  setStep(0);
});

