const move = (ev) => {
  if (!active || active.li !== li) return;
  const dx = ev.clientX - active.startX;
  const dy = ev.clientY - active.startY;
  if (!active.moved) {
    if (Math.hypot(dx, dy) < 6) return;
    active.moved = true;
    li.classList.add("is-dragging");
  } else {
    li.style.transform = `translateY(${ev.clientY - (active.curRect ? active.curRect.top : active.startY)}px)`;
  }
  // позиция относительно списка
  const ulRect = ul.getBoundingClientRect();
  const y = ev.clientY - ulRect.top - active.offsetDY;

  const items = qsa("li", ul).filter((x) => x !== li);
  // ищем, перед каким элементом встанем
  let target = null;
  for (const it of items) {
    const ir = it.getBoundingClientRect();
    const cy = ir.top - ulRect.top + ir.height / 2;
    if (y < cy) { target = it; break; }
  }

  ul.insertBefore(li, target);
  active.curRect = li.getBoundingClientRect();
  qsa("li", ul).forEach((x) => x.classList.toggle("is-over", x !== li && x === target));
  refreshRanks(ul);
  ev.preventDefault();
};

