import re
# extract in DOM order, with pane attribution
def extract(path):
    h=open(path).read()
    out=[]  # list of (pane, [items])
    # find all li blocks with their position
    lis=list(re.finditer(r'data-type="([a-z])">([^<]*)</li>', h))
    panes=[(m.start(), int(m.group(1)), m.end()) for m in re.finditer(r'data-step-pane="(\d+)"', h)]
    for pos,(t,txt) in [(m.start(), m.group(1), m.group(2)) for m in lis]:
        pane=None
        for s,n,e in panes:
            if s<=pos: pane=n
            else: break
        out.append((pane,t,txt))
    return out
mine=extract('index.html')
orig=extract('/tmp/disc.html')
# group consecutive by pane
def group(seq):
    g=[]; 
    for p,t,txt in seq:
        if g and g[-1][0]==p: g[-1][1].append((t,txt))
        else: g.append([p,[(t,txt)]])
    return g
mg=group(mine); og=group(orig)
print("mine panes:", [(p,len(items)) for p,items in mg])
print("orig panes:", [(p,len(items)) for p,items in og])
match = mg==og
print("GROUPS MATCH:", match)
if not match:
    for i in range(max(len(mg),len(og))):
        a=mg[i] if i<len(mg) else None
        b=og[i] if i<len(og) else None
        if a!=b: print("DIFF at",i, a[:1], b[:1] if b else None)
